      // === Industries page ===
      "industries.s01.primary_tag": "Ingeniørrådgivere",
      "industries.s01.body1.intro": "Verdiforslaget er enkelt.",
      "industries.s01.body1.bold": "Rådgivende ingeniører er den dyreste profesjonelle kapasiteten i byggebransjen, og den største delen av tiden deres går til manuell rapportproduksjon — ikke til ingeniørfaglig analyse.",
      "industries.s01.body1.outro": "Builtly snur det forholdet. AI håndterer rutineproduksjonen; ingeniørens tid går til arbeidet som rettferdiggjør honoraret.",
      "industries.s01.body2": "Resultatet for rådgiveren: raskere leveranser, flere prosjekter per senior, og seniorkapasitet endelig brukt på arbeid som faktisk krever det. Resultatet for ingeniøren: mindre papirarbeid, mer dømmekraft.",
      "industries.s01.meta.segment.k": "Segment",
      "industries.s01.meta.segment.v": "Primær",
      "industries.s01.meta.modules.k": "Moduler i bruk",
      "industries.s01.meta.modules.v": "Alle 15",
      "industries.s01.meta.delivery.k": "Leveransenivåer",
      "industries.s01.meta.engagement.k": "Engasjement",
      "industries.s01.meta.engagement.v": "Plattformlisens",
      "industries.s01.pm.h4": "Moduler brukt av rådgivere",
      "industries.s01.pm.desc": "Alle femten, fordelt på tre leveransenivåer",
      "industries.mod.geo": "Geoteknikk",
      "industries.mod.str": "Konstruksjon",
      "industries.mod.fir": "Brannsikkerhet",
      "industries.mod.aco": "Akustikk",
