      "maps.disc.geotech": "Geotekniikka",
      "maps.disc.fire": "Palo",
      "maps.disc.acoustics": "Akustiikka",
      "maps.disc.climate": "Ilmastoriski",
      "maps.disc.valuation": "Arvonmääritys",
      "maps.coverage.label": "Kattavuus",
      "maps.coverage.soon": "Laajenee",
      "maps.country.no": "Norja",
