        "industries.s01.meta.engagement.v": "Plattformlisens",
        "industries.s01.pm.h4": "Moduler tilgjengelig for rådgivere",
        "industries.s01.pm.desc": "Femten moduler på tvers av tre leveransenivåer",
        "industries.mod.geo": "Geoteknikk",
