        "industries.mod.tdd": "Teknisk DD",
        "industries.mod.bid": "Anbudsgranskning",
        "industries.mod.qty": "Mängder",
        "industries.mod.hse": "Arbetsmiljöplan",
        "industries.mod.cli": "Klimatrisk",
        "industries.mod.sus": "Hållbarhet",
