        "industries.s01.pm.desc": "Viisitoista moduulia kolmella toimitustasolla",
        "industries.mod.geo": "Geotekniikka",
        "industries.mod.str": "Rakennesuunnittelu",
        "industries.mod.fir": "Paloturvallisuus",
        "industries.mod.aco": "Akustiikka",
        "industries.mod.env": "Ympäristö",
