      "ref.p6.r": "Anbudsgrunnlag · oversendelser · tilbudsmottak",
      "ref.s01": "Leveranser",
      "ref.s01tag": "Anonymisert etter avtale",
      "ref.side1k": "Prosjekter i aktiv leveranse",
      "ref.side2k": "Navngivning",
